#include <cstring>
#include <span>
#include <string_view>

// Returns false, having written nothing, when the text plus its terminator
// does not fit. The view is never assumed to be terminated: its end is its
// length, so the copy is bounded by size() and not by a scan for a zero.
bool to_c_string(std::string_view text, std::span<char> buffer) {
    if (buffer.size() < text.size() + 1) {
        return false;
    }
    if (!text.empty()) {
        std::memcpy(buffer.data(), text.data(), text.size());
    }
    buffer[text.size()] = '\0';
    return true;
}

#include <string_view>

std::string_view trim(std::string_view text) {
    constexpr std::string_view blanks = " \t";

    const std::size_t first = text.find_first_not_of(blanks);
    if (first == std::string_view::npos) {
        return text.substr(text.size());  // empty, still inside the input
    }

    text.remove_prefix(first);
    const std::size_t last = text.find_last_not_of(blanks);
    text.remove_suffix(text.size() - (last + 1));
    return text;
}

