struct Duration {
    bool ok = false;
    std::int64_t count = 0;
    std::string_view unit;
};

Duration parse_duration(std::string_view text) {
    std::int64_t count = 0;
    const char* const end = text.data() + text.size();
    const auto [next, error] = std::from_chars(text.data(), end, count);

    if (error != std::errc{}) {
        return {};  // invalid_argument or result_out_of_range
    }

    const auto consumed = static_cast<std::size_t>(next - text.data());
    return {true, count, text.substr(consumed)};
}

