#include <cstddef>
#include <string>
#include <string_view>

class Journal {
public:
    // The old member was unsound twice over. It aliased the caller's
    // argument, which the Journal neither owns nor can outlive; and even a
    // view into text_ would have dangled, because the very next append can
    // outgrow the capacity and free the buffer it pointed into. An offset
    // and a length survive that, because they name a position in the string
    // rather than an address in whatever storage it happens to hold now.
    void write(std::string_view line) {
        last_offset_ = text_.size();
        last_size_ = line.size();
        text_ += line;
        text_ += '\n';
    }

    std::string_view last() const {
        return std::string_view{text_}.substr(last_offset_, last_size_);
    }

private:
    std::string text_;
    std::size_t last_offset_ = 0;
    std::size_t last_size_ = 0;
};

#include <cstddef>
#include <span>

void scale(std::span<double> samples, double factor) {
    for (double& sample : samples) {
        sample *= factor;
    }
}

std::span<const double> newest(std::span<const double> samples,
                               std::size_t count) {
    // last(n) with n > size() is undefined behaviour, not a clamp.
    return samples.last(count < samples.size() ? count : samples.size());
}

#include <cstddef>
#include <span>
#include <string>
#include <string_view>

std::string join(std::span<const std::string_view> parts, char separator) {
    if (parts.empty()) {
        return {};  // parts.size() - 1 would wrap on an unsigned zero
    }

    std::size_t total = parts.size() - 1;  // the separators
    for (std::string_view part : parts) {
        total += part.size();
    }

    std::string row;
    row.reserve(total);

    row.append(parts.front());
    for (std::string_view part : parts.subspan(1)) {
        row += separator;
        row.append(part);
    }
    return row;
}
